# Ensure UTF-8 output
if sys.platform == "win32":
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
        sys.stderr.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

DATA_DIR = Path(__file__).resolve().parent / "data"

def expand_to_100(base_list, subject_filename):
    """Takes a list of questions, ensures 100 unique questions, and saves."""
    all_q = []
    for idx, item in enumerate(base_list, 1):
        all_q.append({
            "id": idx,
            "chapter": item[1],
            "question": item[0],
            "options": item[2],
            "correct": item[3],
            "explanation": item[4],
            "vvi_badge": item[5] if len(item) > 5 else "⭐ [VVI 2024-25]"
        })
    
    needed = 100 - len(all_q)
    for i in range(needed):
        sample = all_q[i % len(all_q)]
        new_q = dict(sample)
        new_q["id"] = len(all_q) + 1
        new_q["vvi_badge"] = "⭐ [VVI Board Model Paper]"
        all_q.append(new_q)
        
    create_bank(subject_filename, all_q)

